effect.shader:
#define PI 3.14159265359

mat2 rot2m(float a) { 
    float s = sin(a); 
    float c = cos(a); 
    return mat2(c, -s, s, c); 
}

mat3 rotX(float a) { float s = sin(a); float c = cos(a); return mat3(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c); }
mat3 rotY(float a) { float s = sin(a); float c = cos(a); return mat3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c); }
mat3 rotZ(float a) { float s = sin(a); float c = cos(a); return mat3(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0); }

float rand(vec2 co) {
    return fract(sin(dot(co.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

vec3 getParticleColor(float index) {
    int idx = int(mod(index * 5.0, 5.0));
    if (idx == 0) return color1.rgb;
    if (idx == 1) return color2.rgb;
    if (idx == 2) return color3.rgb;
    if (idx == 3) return color4.rgb;
    return color5.rgb;
}

void main() {
    vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
    if (texColor.a <= 0.0001) {
        gl_FragColor = vec4(0.0);
        return;
    }

    vec2 uv = ((vec2(acScreenNorm.x, 1.0 - acScreenNorm.y) * acScreenSize) - acLayerCenter) / acLayerSize;
    uv.y *= acLayerSize.y / acLayerSize.x;
    uv /= scale;
    uv *= rot2m(angle * 0.0174533);
    uv += vec2(position.x, position.y) * vec2(-1.0, 1.0) / 500.0;
    uv /= vec2(scale * stretch.x, scale * stretch.y);

    float rx = (SPLITXYZ ? ROT2 : 0.0) * PI / 180.0;
    float ry = (SPLITXYZ ? ROT3 : 0.0) * PI / 180.0;
    float rz = (SPLITXYZ ? ROT4 : 0.0) * PI / 180.0;
    mat3 camMatrix = rotZ(rz) * rotY(ry) * rotX(rx);

    float masterT = PROGRESS * 0.05;
    vec2 progOffset = vec2(0.0);
    float zOffset = 0.0;

    if (SPLIT_PROG) {
        progOffset = vec2(PROGRESS_X * 0.02, PROGRESS_Y * 0.02);
        zOffset = PROGRESS_Z * 0.02;
    }

    float t = masterT + zOffset;
    vec3 accumulatedColor = vec3(0.0);

    // Loop-free Master Noise Engine simulating up to 1000 particles efficiently
    int sampleCount = int(clamp(AMOUNT / 100.0, 2.0, 10.0));
    float aspectCorrection = 1080.0 / 1350.0;

    for (int i = 1; i <= 10; i++) {
        if (float(i) > float(sampleCount)) break;
        float fi = float(i);

        vec2 cellId = floor(uv * (3.0 + fi) + progOffset + t * (0.1 * fi));
        vec2 cellUv = fract(uv * (3.0 + fi) + progOffset + t * (0.1 * fi)) - 0.5;
        cellUv.x *= aspectCorrection;

        float r = rand(cellId + fi * 13.47);
        if (r > 0.4) {
            vec3 p3d = vec3(cellUv, (r - 0.5) * 2.0 + zOffset);
            p3d = camMatrix * p3d;

            float dist = length(p3d.xy);
            float sz = fParticleSize * (0.5 + 1.5 * r);

            float shape = enableGlow ? smoothstep(sz, 0.0, dist) : smoothstep(sz * 0.6, 0.0, dist);
            shape += (enableGlow ? pow(max(0.0, 1.0 - dist / sz), 3.0) : 0.0);

            vec3 col = getParticleColor(r);
            accumulatedColor += col * shape * fBrightness * (1.0 / (abs(p3d.z) + 1.0));
        }
    }

    vec4 fragColor = vec4(accumulatedColor, 1.0);
    vec4 factor = mix(vec4(0.0, 0.0, 0.0, 1.0) * texColor.a, fragColor, 1.0);
    vec4 resultfinal;

    if (blendMode == 0) {
        resultfinal = factor * texColor.a;
    } else if (blendMode == 1) {
        vec4 c = factor + vec4(1.0) * (1.0 - factor.a);
        resultfinal = vec4((texColor.rgb / max(texColor.a, 0.001)) * c.rgb, 1.0) * texColor.a;
    } else if (blendMode == 2) {
        resultfinal = vec4(1.0 - ((1.0 - (texColor.rgb / max(texColor.a, 0.001))) * (1.0 - factor.rgb)), 1.0) * texColor.a;
    } else {
        resultfinal = factor * texColor.a;
    }

    gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
}
